  '여유로운', '살짝 힘 뺀', '말 안 해도 아는', '잔잔한', '감도 높은', '잔향 같은'
];
const zigzagSituations: string[] = [
  '출근', '데일리', '여행', '데이트', '주말', '소풍', '약속', '휴가', '파티', '캠퍼스', '하객룩', '홈웨어',
  '기분전환', '가볍게 나가는 날', '뭐 입지 고민될 때', '편하게 멋내고 싶은 날'
];
const zigzagNouns = [
  '실루엣', '컬러감', '포인트', '디테일', '라인', '핏', '무드', '스타일', '여운', '결', '톤', '감촉',
