];
const zigzagAdjToAdv: Record<string, string> = {
  "툭 던진": "툭 던지듯",
  "햇살 같은": "햇살처럼",
  "말 안 해도 아는": "말 안 해도 아는 느낌으로",
  "낙낙한": "낙낙하게",
